INSERT INTO "public"."site_content" ("id", "lang", "content", "created_at", "updated_at", "type") VALUES ('17b84e3a-befa-4903-94db-d242c015425e', null, '{"footer":{"social":{"x":"Twitter url","youtube":"Youtube URL","linkedin":"LI url","instagram":"Instagram url"}}}', '2026-07-01 01:35:37.50419+00', '2026-07-01 01:35:37.50419+00', 'config'), ('2de934dd-3dcc-464c-97be-6793a75d4fd6', 'en', '{"how":{"items":[{"id":"political","body":"We work within real political, institutional, and fiscal constraints.","title":"Political Reality"},{"id":"evidence","body":"We combine data, territorial analysis, and operational insight to prioritize action.","title":"Evidence & Intelligence"},{"id":"capacity","body":"We help institutions coordinate actors, strengthen execution, and sustain implementation over time.","title":"Implementation Capacity"}],"title":"How we work"},"nav":{"cta":"Contact","how":"How we work","team":"Team","what":"What we do","areas":"Areas","contact":"Contact","network":"Networks/Collaboration","solutions":"Solutions"},"hero":{"cta":"Schedule a Conversation","body":"Contextual works with governments, multilaterals, and private sector actors to translate strategic priorities into implementable action across security, justice, urban governance, and institutional delivery.","body2":"We help institutions and investors reduce operational risk, strengthen implementation capacity, and navigate complex political and territorial environments.","headline":"Designing and enabling solutions to complex public problems."},"team":{"title":"Team","members":[{"id":"enrique","bio":"Enrique Betancourt is a public policy, public innovation, and urban governance strategist with experience in security, justice, and institutional reform across Latin America. He previously served as Executive Director of Mexico’s National Center for Crime Prevention and worked within the Presidential Delivery Unit of the Government of Mexico. He holds a Master in Urban Design from Harvard University.","name":"Enrique Betancourt","role":"Co-Founder"},{"id":"jairo","bio":"Jairo García Guerrero is a senior security expert with more than 25 years of experience in citizen security, justice, and defense policy in Colombia and Ecuador. He has held senior leadership positions including Secretary of Security for Bogotá, Secretary of Security and Justice for Cali, and Vice Minister of Strategy and Planning at Colombia’s Ministry of Defense. He studied Political Science and Government at Universidad de los Andes.","name":"Jairo García Guerrero","role":"Co-Founder"},{"id":"flavia","bio":"Flávia Carbonari is an international development and citizen security specialist with experience advising governments and global institutions across Latin America and Africa. She has worked with the World Bank, Inter-American Development Bank, and CAF on violence prevention, gender, and social inclusion. She holds a Master’s degree from Georgetown University.","name":"Flávia Carbonari","role":"Specialist"},{"id":"michel","bio":"Michel Camacho is a public policy and criminal justice expert specializing in citizen security, rule of law, and institutional reform in the Caribbean. He has advised the Inter-American Development Bank, USAID, and justice institutions on police reform and organized crime. He holds an LL.M. from Georgetown University as a Fulbright Scholar.","name":"Michel Camacho","role":"Expert"}]},"what":{"items":[{"id":"security","body":"We support governments and institutions in the design and implementation of citizen security, justice, and violence prevention strategies.","title":"Security & Justice"},{"id":"urban","body":"We help cities and institutions coordinate complex urban challenges through integrated and territorially grounded approaches.","title":"Urban Governance"},{"id":"delivery","body":"We design implementation systems, coordination mechanisms, and strategic follow-up structures that help organizations execute priorities under real-world constraints.","title":"Institutional Delivery"},{"id":"innovation","body":"We help organizations and private sector actors navigate operational, institutional, and territorial complexity to strengthen decision-making and reduce risk.","title":"Public Innovation & Risk Advisory"}],"title":"What we do"},"areas":{"items":["Urban violence and citizen security","Prison and correctional systems","Interinstitutional coordination","Organized crime and territorial governance","Violence prevention","Urban management and public space","Institutional reform","Public innovation and implementation systems"],"title":"Selected Areas of Work"},"footer":{"site":"itscontextual.com","email":"hello@itscontextual.com","location":"Washington, DC"},"contact":{"cta":"Submit","title":"Contact","fields":{"name":"Name","email":"Email","message":"Message","surname":"Surname"},"subtitle":"We will contact you as soon as possible"},"network":{"body":"Contextual collaborates with governments, multilaterals, universities, think tanks, and private sector actors across Latin America and beyond.","label":"Selected networks and collaborations include:","title":"Networks & Collaboration"},"solutions":{"items":[{"id":"clinics","body":"Intensive strategic work sessions designed to align decision-makers, institutions, and operational priorities around complex challenges.","title":"Executive Clinics"},{"id":"units","body":"We design and support strategic follow-up structures that help institutions coordinate, monitor, and sustain implementation priorities.","title":"Delivery Units"},{"id":"roadmaps","body":"We translate political, institutional, and operational priorities into concrete implementation pathways.","title":"Strategic Implementation Roadmaps"},{"id":"risk","body":"We help organizations and investors understand and reduce operational, territorial, and institutional risks in complex environments.","title":"Risk & Context Advisory"}],"title":"Solutions"}}', '2026-06-28 21:49:38.922875+00', '2026-07-01 02:28:04.59939+00', 'static'), ('915d1575-b33a-458c-a745-28061b48ba6d', null, '{"hero":{"image":"hero-city.webp"},"team":{"jairo":"team/team-jairo.webp","enrique":"team/team-enrique.webp"},"network":{"nyu":"logos/nyu.webp","peace":"logos/peace.webp","world":"logos/world.webp"}}', '2026-06-30 05:34:06.306973+00', '2026-06-30 20:19:30.831354+00', 'media'), ('b0d4b2f8-dd1c-423d-8902-f60492901b69', 'es', '{"how":{"items":[{"id":"political","body":"We work within real political, institutional, and fiscal constraints.","title":"Political Reality"},{"id":"evidence","body":"We combine data, territorial analysis, and operational insight to prioritize action.","title":"Evidence & Intelligence"},{"id":"capacity","body":"We help institutions coordinate actors, strengthen execution, and sustain implementation over time.","title":"Implementation Capacity"}],"title":"How we work"},"nav":{"cta":"Contact","how":"How we work","team":"Team","what":"What we do","areas":"Areas","contact":"Contact","network":"Networks & Collaboration","solutions":"Solutions"},"hero":{"cta":"Schedule a Conversation","body":"Contextual works with governments, multilaterals, and private sector actors to translate strategic priorities into implementable action across security, justice, urban governance, and institutional delivery.","body2":"We help institutions and investors reduce operational risk, strengthen implementation capacity, and navigate complex political and territorial environments.","headline":"Designing and enabling solutions to complex public problems."},"team":{"title":"Team","members":[{"id":"enrique","bio":"Enrique Betancourt is a public policy, public innovation, and urban governance strategist with experience in security, justice, and institutional reform across Latin America. He previously served as Executive Director of Mexico’s National Center for Crime Prevention and worked within the Presidential Delivery Unit of the Government of Mexico. He holds a Master in Urban Design from Harvard University.","name":"E